class Solution:
    def countDivisiblePairs(self, nums: List[int], k: int) -> int:
        n = len(nums)
        total = 0
        for i in range(n):
            for j in range(i + 1, n):
                if (nums[i] + nums[j]) % k == 0:
                    total += 1
        return total

