class Solution:
    def countDivisiblePairs(self, nums: List[int], k: int) -> int:
        count = [0] * k
        for x in nums:
            count[x % k] += 1
        total = count[0] * (count[0] - 1) // 2
        r = 1
        while r < k - r:
            total += count[r] * count[k - r]
            r += 1
        if k % 2 == 0:
            c = count[k // 2]
            total += c * (c - 1) // 2
        return total

