        long[] count = new long[k];
        for (int x : nums) count[x % k]++;
        long total = count[0] * (count[0] - 1) / 2;
        for (int r = 1; r < k - r; r++) {
            total += count[r] * count[k - r];
        }
        if (k % 2 == 0) {
            long c = count[k / 2];
            total += c * (c - 1) / 2;
        }
        return total;
    }
}

