long long countDivisiblePairs(int* nums, int numsSize, int k) {
    long long* count = calloc(k, sizeof(long long));
    for (int i = 0; i < numsSize; i++) count[nums[i] % k]++;
    long long total = count[0] * (count[0] - 1) / 2;
    for (int r = 1; r < k - r; r++) {
        total += count[r] * count[k - r];
    }
    if (k % 2 == 0) {
        long long c = count[k / 2];
        total += c * (c - 1) / 2;
    }
    free(count);
    return total;
}

